import { mkdirSync, watch } from "node:fs";
import { readdir, readFile, rm, stat } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { buildBitfabRequestHeaders } from "../clientHeaders.js";
import { getConfig } from "../config.js";
import { parseArgs } from "../parseArgs.js";
import { buildExperimentsPath } from "./openExperiments.js";
export const MIN_REFRESH_GAP_MS = 2_000;
export const STREAM_FALLBACK_REFRESH_MS = 60_000;
export const POLL_FALLBACK_REFRESH_MS = 20_000;
export const STREAM_RETRY_MS = 5_000;
export const STALL_AFTER_MS = 10 * 60_000;
export const IDLE_RECHECK_MS = 15_000;
const REQUEST_TIMEOUT_MS = 30_000;
export const LOGIN_RECHECK_MS = 30_000;
export const LAUNCH_LOOKUP_MAX_MS = 60 * 60_000;
const NEVER = new Promise(() => { });
const EXPERIMENT_EVENT_TYPES = new Set([
    "experiment:updated",
    "experiment-stats:updated",
]);
const SAFE_SESSION_ID = /^[A-Za-z0-9_-][A-Za-z0-9._-]*$/;
const LAUNCH_ID_METADATA_KEY = "bitfab-launch-id";
export const SESSION_FOLDER_MAX_AGE_MS = 7 * 24 * 60 * 60_000;
class Waker {
    resolveWake;
    pending;
    constructor() {
        this.pending = this.fresh();
    }
    fresh() {
        return new Promise((resolve) => {
            this.resolveWake = resolve;
        });
    }
    get next() {
        return this.pending;
    }
    wake() {
        this.resolveWake?.();
    }
    reset() {
        this.pending = this.fresh();
    }
}
function progressTotal(status) {
    return status.remainingCount === null
        ? null
        : status.finishedCount + status.remainingCount;
}
export async function watchSessionExperiments(deps) {
    const names = new Map();
    const pendingLaunches = new Map();
    const settledLaunches = new Set();
    const ignored = new Set();
    const finished = new Map();
    const lastProgress = new Map();
    const waker = new Waker();
    let stream = null;
    let streamUnavailable = false;
    let firstPass = true;
    let lastEmitted = "";
    let running = [];
    const isStalled = (id, status) => {
        const now = deps.now();
        const seen = lastProgress.get(id);
        if (seen === undefined || seen.finished !== status.finishedCount) {
            lastProgress.set(id, { finished: status.finishedCount, at: now });
            return false;
        }
        const tracesLeft = status.remainingCount === null || status.remainingCount > 0;
        return tracesLeft && now - seen.at >= STALL_AFTER_MS;
    };
    const onEvent = (event) => {
        if (names.has(event.experimentId) && !finished.has(event.experimentId)) {
            waker.wake();
        }
    };
    const openStream = () => {
        if (stream !== null || streamUnavailable) {
            return;
        }
        const controller = new AbortController();
        stream = controller;
        void (async () => {
            while (!controller.signal.aborted) {
                const outcome = await deps
                    .openStream(onEvent, controller.signal)
                    .catch(() => "ended");
                if (outcome === "unavailable") {
                    streamUnavailable = true;
                    return;
                }
                if (!controller.signal.aborted) {
                    await deps.wait(STREAM_RETRY_MS, NEVER);
                }
            }
        })();
    };
    const closeStream = () => {
        stream?.abort();
        stream = null;
    };
    const track = (id, name) => {
        if (!names.has(id) || name !== null) {
            names.set(id, name);
        }
    };
    const resolveLaunches = async () => {
        for (const [launchId, line] of pendingLaunches) {
            const expired = line.startedAt !== null &&
                deps.now() - line.startedAt > LAUNCH_LOOKUP_MAX_MS;
            if (expired) {
                pendingLaunches.delete(launchId);
                settledLaunches.add(launchId);
                continue;
            }
            const found = await deps.findLaunch(launchId);
            if (found !== null) {
                track(found.id, line.name ?? found.name);
                pendingLaunches.delete(launchId);
                settledLaunches.add(launchId);
            }
        }
    };
    const refresh = async () => {
        for (const line of await deps.readSessionExperiments()) {
            if (line.experimentId !== null) {
                track(line.experimentId, line.name);
            }
            else if (line.launchId !== null &&
                !settledLaunches.has(line.launchId)) {
                pendingLaunches.set(line.launchId, line);
            }
        }
        await resolveLaunches();
        const nowRunning = [];
        for (const [id, name] of names) {
            if (finished.has(id) || ignored.has(id)) {
                continue;
            }
            const status = await deps.readStatus(id);
            if (status === null) {
                ignored.add(id);
            }
            else if (status.status === "pending") {
                nowRunning.push({
                    id,
                    name,
                    finished: status.finishedCount,
                    total: progressTotal(status),
                    url: deps.experimentUrl(id),
                    stalled: isStalled(id, status),
                });
            }
            else if (firstPass) {
                ignored.add(id);
            }
            else {
                finished.set(id, {
                    id,
                    name,
                    status: status.status,
                    url: deps.experimentUrl(id),
                });
            }
        }
        return nowRunning;
    };
    const stopWatchingFile = deps.watchSessionFile(() => waker.wake());
    try {
        while (!deps.shouldStop()) {
            waker.reset();
            const refreshedAt = deps.now();
            const refreshed = await refresh().catch(() => null);
            if (refreshed !== null) {
                firstPass = false;
                running = refreshed;
            }
            const snapshot = {
                running,
                finished: [...finished.values()],
            };
            const key = JSON.stringify(snapshot);
            if (refreshed !== null && key !== lastEmitted) {
                deps.emit(snapshot);
                lastEmitted = key;
            }
            let waitMs;
            if (running.length > 0) {
                openStream();
                waitMs =
                    stream !== null && !streamUnavailable && refreshed !== null
                        ? STREAM_FALLBACK_REFRESH_MS
                        : POLL_FALLBACK_REFRESH_MS;
            }
            else {
                closeStream();
                waitMs = refreshed === null ? POLL_FALLBACK_REFRESH_MS : IDLE_RECHECK_MS;
            }
            await deps.wait(waitMs, waker.next);
            const sinceRefresh = deps.now() - refreshedAt;
            if (sinceRefresh < MIN_REFRESH_GAP_MS) {
                await deps.wait(MIN_REFRESH_GAP_MS - sinceRefresh, NEVER);
            }
        }
    }
    finally {
        stopWatchingFile();
        closeStream();
    }
}
export function parseExperimentEvent(message) {
    if (message.event === null || !EXPERIMENT_EVENT_TYPES.has(message.event)) {
        return null;
    }
    let parsed;
    try {
        parsed = JSON.parse(message.data);
    }
    catch {
        return null;
    }
    if (typeof parsed !== "object" || parsed === null) {
        return null;
    }
    const data = parsed;
    const experimentId = data.experimentId ?? data.testRunId;
    return typeof experimentId === "string" ? { experimentId } : null;
}
function fieldValue(line, field) {
    return line.startsWith(`${field}:`)
        ? line.slice(field.length + 1).trimStart()
        : null;
}
export function splitSseData(buffer) {
    const blocks = buffer.split(/\r?\n\r?\n/);
    const rest = blocks.pop() ?? "";
    const messages = blocks.flatMap((block) => {
        const lines = block.split(/\r?\n/);
        const data = lines
            .map((line) => fieldValue(line, "data"))
            .filter((value) => value !== null)
            .join("\n");
        const event = lines
            .map((line) => fieldValue(line, "event"))
            .find((value) => value !== null) ?? null;
        return data.length > 0 ? [{ event, data }] : [];
    });
    return { messages, rest };
}
async function readEventStream(url, headers, onEvent, signal) {
    const response = await fetch(url, {
        headers: { ...headers, Accept: "text/event-stream" },
        signal,
    });
    if (response.status === 404) {
        return "unavailable";
    }
    if (!response.ok || response.body === null) {
        return "ended";
    }
    const decoder = new TextDecoder();
    const reader = response.body.getReader();
    let buffer = "";
    while (true) {
        const { done, value } = await reader.read();
        if (done) {
            return "ended";
        }
        buffer += decoder.decode(value, { stream: true });
        const { messages, rest } = splitSseData(buffer);
        buffer = rest;
        for (const message of messages) {
            const event = parseExperimentEvent(message);
            if (event !== null) {
                onEvent(event);
            }
        }
    }
}
export function sessionExperimentsPath(home, agentSessionId) {
    return SAFE_SESSION_ID.test(agentSessionId)
        ? path.join(home, ".bitfab", "agent-sessions", agentSessionId)
        : null;
}
function sameServer(left, right) {
    try {
        return new URL(left).origin === new URL(right).origin;
    }
    catch {
        return false;
    }
}
function textOrNull(value) {
    return typeof value === "string" && value.length > 0 ? value : null;
}
export function parseSessionExperiments(content, serviceUrl) {
    return content.split("\n").flatMap((text) => {
        let parsed;
        try {
            parsed = JSON.parse(text);
        }
        catch {
            return [];
        }
        if (typeof parsed !== "object" || parsed === null) {
            return [];
        }
        const record = parsed;
        const experimentId = textOrNull(record.experimentId);
        const launchId = textOrNull(record.launchId);
        if ((experimentId === null && launchId === null) ||
            typeof record.serviceUrl !== "string" ||
            !sameServer(record.serviceUrl, serviceUrl)) {
            return [];
        }
        const startedAt = typeof record.startedAt === "string" ? Date.parse(record.startedAt) : NaN;
        return [
            {
                experimentId,
                launchId,
                name: textOrNull(record.name),
                startedAt: Number.isNaN(startedAt) ? null : startedAt,
            },
        ];
    });
}
async function lastWrittenAt(folder) {
    const file = await stat(path.join(folder, "experiments.jsonl")).catch(() => null);
    return (file ?? (await stat(folder))).mtimeMs;
}
export async function pruneStaleSessionFolders(root, keepSessionId, now) {
    const entries = await readdir(root, { withFileTypes: true }).catch(() => []);
    const removed = [];
    for (const entry of entries) {
        if (!entry.isDirectory() ||
            entry.name === keepSessionId ||
            !SAFE_SESSION_ID.test(entry.name)) {
            continue;
        }
        const folder = path.join(root, entry.name);
        try {
            if (now - (await lastWrittenAt(folder)) >= SESSION_FOLDER_MAX_AGE_MS) {
                await rm(folder, { recursive: true, force: true });
                removed.push(entry.name);
            }
        }
        catch { }
    }
    return removed;
}
async function readSessionFile(directory, serviceUrl) {
    if (directory === null) {
        return [];
    }
    try {
        const content = await readFile(path.join(directory, "experiments.jsonl"), "utf8");
        return parseSessionExperiments(content, serviceUrl);
    }
    catch {
        return [];
    }
}
function watchDirectory(directory, onChange) {
    if (directory === null) {
        return () => { };
    }
    try {
        mkdirSync(directory, { recursive: true });
        const watcher = watch(directory, () => onChange());
        watcher.on("error", () => watcher.close());
        return () => watcher.close();
    }
    catch {
        return () => { };
    }
}
function isListedExperiment(value) {
    if (typeof value !== "object" || value === null) {
        return false;
    }
    const record = value;
    return (typeof record.id === "string" &&
        (record.name === null || typeof record.name === "string"));
}
async function findLaunchFromApi(serviceUrl, headers, launchId) {
    const params = new URLSearchParams({
        metadata: JSON.stringify({ [LAUNCH_ID_METADATA_KEY]: launchId }),
        limit: "1",
    });
    const response = await fetch(`${serviceUrl}/api/sdk/experiments?${params.toString()}`, { headers, signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
    if ([400, 403, 404].includes(response.status)) {
        return null;
    }
    if (!response.ok) {
        throw new Error(`Bitfab returned ${response.status} finding launch ${launchId}`);
    }
    const body = (await response.json());
    const found = (body.experiments ?? []).find(isListedExperiment);
    return found === undefined ? null : { id: found.id, name: found.name };
}
async function readStatusFromApi(serviceUrl, headers, experimentId) {
    const response = await fetch(`${serviceUrl}/api/sdk/replay/status`, {
        method: "POST",
        headers,
        body: JSON.stringify({ experimentId }),
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    if ([400, 403, 404].includes(response.status)) {
        return null;
    }
    if (!response.ok) {
        throw new Error(`Bitfab returned ${response.status} reading experiment ${experimentId}`);
    }
    return (await response.json());
}
const FLAGS = [
    {
        name: "agent-session-id",
        description: "The coding agent session whose experiments to follow: the ones its replays wrote to ~/.bitfab/agent-sessions/<id>/experiments.jsonl.",
    },
];
export async function runWatchRunningExperiments(platform, pluginVersion) {
    const { flags } = parseArgs({
        positional: [],
        flags: FLAGS,
        description: "Follow the experiments a coding agent session's replays started, printing them as JSON, one line each time they change. Runs until the session ends, waiting for a login when there is none and retrying through failed requests. Replays record each experiment they start in ~/.bitfab/agent-sessions/<session id>/experiments.jsonl (a --cloud replay records its launch id instead, and the experiment tagged bitfab-launch-id=<launch id> is looked up for up to an hour); experiments on another Bitfab server, or ones this API key cannot read, are left out. Opens Bitfab's pushed experiment events only while one runs. On start it deletes other sessions' folders there that nothing has written to for 7 days.",
    });
    const agentSessionId = flags["agent-session-id"];
    if (typeof agentSessionId !== "string" || agentSessionId.length === 0) {
        throw new Error("Pass --agent-session-id <session id>.");
    }
    const parentPid = process.ppid;
    process.stdout.on("error", () => process.exit(0));
    let config = getConfig();
    while (!config.apiKey) {
        if (process.ppid !== parentPid) {
            process.exit(0);
        }
        await new Promise((resolve) => setTimeout(resolve, LOGIN_RECHECK_MS));
        config = getConfig();
    }
    const headers = buildBitfabRequestHeaders(config.apiKey, pluginVersion, platform);
    const serviceUrl = config.serviceUrl.replace(/\/$/, "");
    const directory = sessionExperimentsPath(os.homedir(), agentSessionId);
    void pruneStaleSessionFolders(path.join(os.homedir(), ".bitfab", "agent-sessions"), agentSessionId, Date.now());
    await watchSessionExperiments({
        readSessionExperiments: () => readSessionFile(directory, serviceUrl),
        findLaunch: (launchId) => findLaunchFromApi(serviceUrl, headers, launchId),
        watchSessionFile: (onChange) => watchDirectory(directory, onChange),
        readStatus: (id) => readStatusFromApi(serviceUrl, headers, id),
        experimentUrl: (id) => `${serviceUrl}${buildExperimentsPath([id])}`,
        openStream: (onEvent, signal) => readEventStream(`${serviceUrl}/api/plugin/experimentEvents`, headers, onEvent, signal),
        emit: (snapshot) => console.log(JSON.stringify(snapshot)),
        now: () => Date.now(),
        wait: (ms, wake) => Promise.race([
            wake,
            new Promise((resolve) => setTimeout(resolve, ms)),
        ]),
        shouldStop: () => process.ppid !== parentPid,
    });
    process.exit(0);
}
